CREATE SEQUENCE IF NOT EXISTS order_number_seq START WITH 1001;
CREATE TABLE IF NOT EXISTS coupons (code text PRIMARY KEY CHECK(code=upper(code) AND code~'^[A-Z0-9_-]{3,32}$'),discount_percent smallint NOT NULL CHECK(discount_percent BETWEEN 1 AND 100),active boolean NOT NULL DEFAULT true,starts_at timestamptz,ends_at timestamptz,max_redemptions integer CHECK(max_redemptions IS NULL OR max_redemptions>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at));
CREATE TABLE IF NOT EXISTS orders (id uuid PRIMARY KEY,order_number bigint NOT NULL UNIQUE DEFAULT nextval('order_number_seq'),status text NOT NULL CHECK(status IN ('pending','paid','failed','cancelled')),customer jsonb NOT NULL,items jsonb NOT NULL,shipping_method text NOT NULL,subtotal_agorot integer NOT NULL,shipping_agorot integer NOT NULL,discount_agorot integer NOT NULL DEFAULT 0,coupon_code text REFERENCES coupons(code),discount_percent smallint,total_agorot integer NOT NULL,sumit_payment_id text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),paid_at timestamptz,customer_email_sent_at timestamptz,merchant_email_sent_at timestamptz,email_last_error text);
CREATE INDEX IF NOT EXISTS orders_status_created_idx ON orders(status,created_at DESC);
CREATE TABLE IF NOT EXISTS coupon_redemptions (order_id uuid PRIMARY KEY REFERENCES orders(id) ON DELETE CASCADE,coupon_code text NOT NULL REFERENCES coupons(code),status text NOT NULL CHECK(status IN ('reserved','paid')),reserved_at timestamptz NOT NULL DEFAULT now(),expires_at timestamptz NOT NULL,paid_at timestamptz);
CREATE INDEX IF NOT EXISTS coupon_redemptions_availability_idx ON coupon_redemptions(coupon_code,status,expires_at);
